#!/bin/zsh
# Updated by SecurityShrimp 2026 # Jamf Certificate-Based Communication Extension Attribute # Targets macOS 12 through 26 (Tahoe), Intel and Apple Silicon
if [[ -f "/Library/Application Support/JAMF/JAMF.keychain" ]]; then echo "<result>Enabled</result>" else echo "<result>Not Enabled</result>" fi
